  function fillPanel(row){ pIcon.src=ICONS+row.getAttribute('data-icon')+'.svg'; pTitle.textContent=row.querySelector('.bb-solution__name').textContent; pText.innerHTML=row.querySelector('.bb-solution__detail').innerHTML; }
  function select(row,swap){ if(row===current) return; current=row;
    rows.forEach(function(r){ var on=r===row; r.classList.toggle('bb-solution--active',on); r.querySelector('.bb-solution__btn').setAttribute('aria-expanded',String(on)); });
    if(swap&&wide.matches){ panel.classList.add('bb-solution-picker__panel--swapping'); window.setTimeout(function(){ fillPanel(row); panel.classList.remove('bb-solution-picker__panel--swapping'); },180); } else { fillPanel(row); } }
  rows.forEach(function(row){ var btn=row.querySelector('.bb-solution__btn');
    btn.addEventListener('click',function(){ if(!wide.matches&&row===current){ row.classList.remove('bb-solution--active'); btn.setAttribute('aria-expanded','false'); current=null; return; } select(row,true); });
    btn.addEventListener('mouseenter',function(){ if(wide.matches) select(row,true); }); });
  panel.hidden=false; root.classList.add('bb-solution-picker--live'); select(rows[0],false);
})();
</script>
